{"args":{"content":""""Build a [HANDOFF] body from ledger rows and rulings sections.

usage: python mkhandoff.py <ledger.md> <rulings.md> <header-file> <ids> <rulings> <out>
ids: comma list of A-numbers/ranges, e.g. 3-5,31,56-67 ; rulings: comma list like 1,2,7
"""
import re
import sys

ledger, rulings, header, ids, rids, out = sys.argv[1:7]


def expand(spec):
    res = []
    for part in spec.split(","):
        part = part.strip()
        if not part:
            continue
        if "-" in part:
            a, b = part.split("-")
            res.extend(range(int(a), int(b) + 1))
        else:
            res.append(int(part))
    return res


rows = {}
for line in open(ledger, encoding="utf-8"):
    m = re.match(r"\| A(\d+) \| (.*)$", line)
    if m:
        cells = [c.strip() for c in m.group(2).split(" | ")]
        rows[int(m.group(1))] = cells

text = open(rulings, encoding="utf-8").read()
secs = {}
for m in re.finditer(r"^## R-(\d+) — .*?(?=^## R-|\Z)", text, re.S | re.M):
    secs[int(m.group(1))] = m.group(0).strip()

parts = [open(header, encoding="utf-8").read().rstrip(), "", "## Requirement text and acceptance criteria", ""]
for n in expand(ids):
    c = rows[n]
    quote, beh, prec, acc = c[0], c[1], c[2], c[3]
    parts.append(f"- **C1.{n}** — {quote}")
    if beh:
        parts.append(f"  - behaviour: {beh}")
    if prec and prec != "n/a":
        parts.append(f"  - precedence: {prec}")
    if acc and acc != "n/a":
        parts.append(f"  - acceptance: {acc}")
if rids:
    parts += ["", "## Binding rulings", ""]
    for r in expand(rids):
        parts.append(secs[r])
        parts.append("")
open(out, "w", encoding="utf-8", newline="\n").write("\n".join(parts) + "\n")
print(out, len("\n".join(parts)))
